function modedata = importfile_sph(filename, dataLines)
%IMPORTFILE_SPH  Read the numeric body of a TICRA .sph file as a table.
%  modedata = IMPORTFILE_SPH(FILENAME) reads the space-delimited numeric
%  columns of FILENAME from line 3 onward (the first two header lines are
%  skipped) and returns them as a 4-column table.
%
%  modedata = IMPORTFILE_SPH(FILENAME, DATALINES) reads the row interval(s)
%  DATALINES (positive scalar or N-by-2 array of [first last] rows).
%
%  Example:
%  modedata = importfile_sph("antenna_FarField1.sph", [3, Inf]);
%
%  See also READTABLE, ReadSphModes.
%
% Auto-generated by MATLAB on 22-Feb-2024 13:20:08 with additional comments
% by D B Davidson

%% Input handling

% If dataLines is not specified, define defaults
if nargin < 2
    dataLines = [3, Inf];
end

%% Set up the Import Options and import the data
opts = delimitedTextImportOptions("NumVariables", 5);

% Specify range and delimiter
opts.DataLines = dataLines;
opts.Delimiter = " ";

% Specify column names and types
opts.VariableNames = ["TICRA", "SWE", "file", "export", "Var5"];
opts.SelectedVariableNames = ["TICRA", "SWE", "file", "export"];
opts.VariableTypes = ["double", "double", "double", "double", "string"];

% Specify file level properties
opts.ExtraColumnsRule = "ignore";
opts.EmptyLineRule = "read";
opts.ConsecutiveDelimitersRule = "join";
opts.LeadingDelimitersRule = "ignore";

% Specify variable properties
opts = setvaropts(opts, "Var5", "WhitespaceRule", "preserve");
opts = setvaropts(opts, "Var5", "EmptyFieldRule", "auto");
opts = setvaropts(opts, "TICRA", "TrimNonNumeric", true);
opts = setvaropts(opts, "TICRA", "ThousandsSeparator", ",");

% Import the data
modedata = readtable(filename, opts);

end